import{_ as a,C as i,o as n,c as r,E as o,a2 as d}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.8","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.8","type":"implementation-case","domain":"TMPA","version":"I0.8","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i0.8.md","filePath":"en/publications/implementation-case-i0.8.md","lastUpdated":1786339128000}'),s={name:"en/publications/implementation-case-i0.8.md"};function c(l,e,p,u,h,m){const t=i("ArticleCover");return n(),r("div",null,[o(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"An exact-input TMPA Core S0.6 product run and self-contained public reproducer for CodeFlowMu V1.6.0.",version:"I0.8",status:"S0.6 product evidence draft · 14/14 PASS",languageHref:"/zh/publications/implementation-case-i0.8",languageLabel:"简体中文"}),e[0]||(e[0]=d(`<p>status=&quot;S0.6 product evidence draft · 14/14 PASS&quot; languageHref=&quot;/zh/publications/implementation-case-i0.8&quot; languageLabel=&quot;简体中文&quot; /&gt;</p><h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="tmpa-core-s0-6-fcop-codeflowmu-v1-6-0-and-retained-field-evidence" tabindex="-1">TMPA Core S0.6, FCoP, CodeFlowMu V1.6.0, and retained field evidence <a class="header-anchor" href="#tmpa-core-s0-6-fcop-codeflowmu-v1-6-0-and-retained-field-evidence" aria-label="Permalink to &quot;TMPA Core S0.6, FCoP, CodeFlowMu V1.6.0, and retained field evidence&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.8<br><strong>Status:</strong> Author-produced implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s0.6">TMPA Core Specification S0.6</a>, commit <code>8989657e8fde6d2e55d7606ae0adacac14fec760</code><br><strong>Product Under Test:</strong> CodeFlowMu V1.6.0, implementation commit <code>62440a526a99d2fe55019d8bb95ad2425569fcb4</code><br><strong>Evidence Capture:</strong> 2026-08-10, Asia/Shanghai<br><strong>Formal Evidence Package:</strong> <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip</code><br><strong>Archive SHA-256:</strong> <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. Only the Core Specification defines TMPA requirements.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I0.8 evaluates CodeFlowMu V1.6.0 against all fourteen mandatory criteria in TMPA Core S0.6 using the exact raw-LF bytes fixed by the normative repository commit. The product-level result is <strong>14 PASS, 0 PARTIAL, 0 NOT RUN, and 0 FAIL</strong>. CodeFlowMu&#39;s product runner calls its own synchronous <code>GovernanceReader</code> and does not invoke the TMPA Reference Reader. The input bundle digest is <code>sha256:251914ee55922d20c9bd23943a4ff445bccaa5835e1fcc11b8562f3f384243fa</code>.</p><p>The engineering upgrade closes the observable S0.6 delta over the I0.7/S0.5 baseline: byte-identical observations retain every contributing source ID; high-risk approval requires a permitted decision-object type, a valid role assignment, an allowed role, an approval decision, and an independent actor when required; and every canonical sort uses locale-independent Unicode code-point order, including a regression over U+E000 and U+10000. CodeFlowMu&#39;s internal TMPA suite passes 23/23 tests, Runtime records 1,485 passed / 0 failed / 1 skipped, Shell records 777/777, and the locked FCoP reference implementation records 1,210 passed / 2 skipped.</p><p>The evidence archive includes a self-contained public reproducer. A clean <code>npm ci</code> and <code>npm test</code> run verifies the seven official S0.6 byte digests and executes the bundled CodeFlowMu product Reader with 14/14 PASS; no private CodeFlowMu checkout is required for this conformance slice. The strongest supportable claim remains <strong>author-run demonstrated behavior under a fixed bundle</strong>. The result is not independent certification, independent adoption, a proof for arbitrary inputs, or proof that AI hallucinations have been eliminated.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>I0.8 asks:</p><ol><li>Does the CodeFlowMu V1.6.0 product Reader satisfy S0.6 C01–C14 against one exact, fixed input bundle?</li><li>Are the three observable S0.6 changes—source provenance retention, complete human-approval authorization, and locale-independent ordering—implemented without regressing the S0.5 behavior demonstrated by I0.7?</li><li>Can the conformance slice be rerun without access to the private CodeFlowMu mother repository?</li><li>Which evidence remains author-local, and which conclusions remain unsupported?</li></ol><p>The unit of judgment is a criterion-bound claim over a fixed bundle. The four evidence levels remain separate:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning in I0.8</th><th style="text-align:right;">Reached?</th></tr></thead><tbody><tr><td>Specified</td><td>Defined normatively by TMPA Core S0.6</td><td style="text-align:right;">Yes</td></tr><tr><td>Implemented</td><td>A corresponding CodeFlowMu mechanism exists</td><td style="text-align:right;">Yes</td></tr><tr><td>Demonstrated</td><td>An execution produced inspectable evidence</td><td style="text-align:right;">Yes, for the fixed C01–C14 bundle</td></tr><tr><td>Independently Adopted</td><td>A separate organization adopted and validated the mechanism</td><td style="text-align:right;">No</td></tr></tbody></table><h1 id="_2-architecture-and-evidence-boundaries" tabindex="-1">2. Architecture and Evidence Boundaries <a class="header-anchor" href="#_2-architecture-and-evidence-boundaries" aria-label="Permalink to &quot;2. Architecture and Evidence Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ theory guides engineering direction</span></span>
<span class="line"><span>TMPA Core S0.6</span></span>
<span class="line"><span>        ↓ fixes normative object, Reader, and conformance contract</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>        ↓ supplies the collaboration and evidence protocol</span></span>
<span class="line"><span>CodeFlowMu V1.6.0 execution and consumption layer</span></span>
<span class="line"><span>        ↓ product Reader, Runtime, roles, recovery, and audit</span></span>
<span class="line"><span>WP-13 and other bounded cases</span></span></code></pre></div><p>TMPA theory guides the engineering direction of CodeFlowMu, while Core S0.6 fixes the normative behavior evaluated in this report. FCoP is the reusable collaboration and evidence protocol used by CodeFlowMu, not an application; <code>fcop</code> and <code>fcop-mcp</code> are reference implementations rather than the protocol itself. Consistent with CodeFlowMu&#39;s engineering architecture [7], CodeFlowMu is the application execution and consumption layer: it produces coordination facts, runs the Adapter and Reader, projects the governance graph, and lets recovery and governance gates consume the reconstructed result. WP-13 remains a bounded evidence-admission case. XiaoDian AI is retained as author-reported engineering lineage only and is excluded from the evaluated evidence; neither substitutes for the S0.6 product run.</p><p>Conceptual dependency and historical formation remain distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CURRENT GUIDANCE: TMPA theory → Core requirements → FCoP protocol</span></span>
<span class="line"><span>                                                  → CodeFlowMu engineering</span></span>
<span class="line"><span>HISTORICAL FEEDBACK: XiaoDian practice → early TMPA → FCoP extraction</span></span>
<span class="line"><span>                                           → CodeFlowMu implementation</span></span>
<span class="line"><span>FCoP + CodeFlowMu results → current TMPA formalization</span></span></code></pre></div><p>Historical feedback explains how the theory matured; it does not invert the current authority relation. Product behavior may provide evidence or motivate a later revision, but it cannot redefine the current Core.</p><h1 id="_3-fixed-sources-and-evidence-design" tabindex="-1">3. Fixed Sources and Evidence Design <a class="header-anchor" href="#_3-fixed-sources-and-evidence-design" aria-label="Permalink to &quot;3. Fixed Sources and Evidence Design&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Source</th><th>Fixed identity</th><th>Role in I0.8</th><th>Boundary</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.6, commit <code>8989657…</code></td><td>Normative C01–C14 target</td><td>Specification, not product evidence</td></tr><tr><td>CodeFlowMu</td><td>V1.6.0, commit <code>62440a5…</code></td><td>Product implementation under test</td><td>Local implementation commit; not represented as a public release</td></tr><tr><td>Public reproducer</td><td>29 locked files</td><td>Public rerun of the conformance slice</td><td>Does not expose or reproduce the entire private product</td></tr><tr><td>FCoP reference implementation</td><td>commit <code>da79dfe…</code></td><td>Locked dependency baseline</td><td>Test result is not proof of the abstract protocol</td></tr><tr><td>I0.7</td><td>S0.5 / CodeFlowMu V1.4.1</td><td>Historical regression baseline</td><td>Retained with its exact earlier meaning</td></tr><tr><td>WP-13 V3</td><td>Previously published package</td><td>Evidence-gating field case</td><td>Not rerun and not promoted to a conformance proof</td></tr></tbody></table><p>The seven official S0.6 inputs—four schemas, canonicalization profile, lifecycle profile, and fixtures—are byte-identical to GitHub. The first submitted archive had Windows checkout-converted CRLF copies; publication preflight rejected it. The final archive uses raw Git blob bytes, reruns the product criteria, and regenerates every dependent digest instead of editing prior result JSON.</p><h1 id="_4-executed-test-baseline" tabindex="-1">4. Executed Test Baseline <a class="header-anchor" href="#_4-executed-test-baseline" aria-label="Permalink to &quot;4. Executed Test Baseline&quot;">​</a></h1><p>All primary product and full-suite runs were author-executed against fixed inputs. Skipped tests remain skips.</p><table tabindex="0"><thead><tr><th>Track</th><th style="text-align:right;">Result</th><th style="text-align:right;">Exit</th><th>Interpretation</th></tr></thead><tbody><tr><td>S0.6 product C01–C14</td><td style="text-align:right;">14 PASS / 0 FAIL / 0 PARTIAL / 0 NOT RUN</td><td style="text-align:right;">0</td><td>Direct CodeFlowMu product Reader execution</td></tr><tr><td>CodeFlowMu internal TMPA</td><td style="text-align:right;">23/23</td><td style="text-align:right;">0</td><td>Includes explicit S0.5 compatibility and S0.6 regressions</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">5 valid + 3 expected-invalid fixtures</td><td style="text-align:right;">0</td><td>Product protocol tests, separate from TMPA verdict</td></tr><tr><td>Protocol / Runtime / Shell type checks</td><td style="text-align:right;">all passed</td><td style="text-align:right;">0</td><td>Static checks only</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,485 passed, 0 failed, 1 skipped</td><td style="text-align:right;">0</td><td>Full author-local Runtime run</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">777 passed, 0 failed</td><td style="text-align:right;">0</td><td>Full author-local Shell run</td></tr><tr><td>FCoP locked reference baseline</td><td style="text-align:right;">1,210 passed, 2 skipped</td><td style="text-align:right;">0</td><td>Reference implementation, not protocol proof</td></tr><tr><td>Public reproducer</td><td style="text-align:right;"><code>npm ci</code> + 14/14 product PASS</td><td style="text-align:right;">0</td><td>Self-contained conformance-slice rerun</td></tr></tbody></table><p>The final conformance result validates against the S0.6 result schema. It records <code>product_reader_called: true</code>, <code>reference_reader_called: false</code>, implementation <code>codeflowmu/V1.6.0</code>, and evidence level <code>demonstrated</code>.</p><h1 id="_5-c01–c14-product-results" tabindex="-1">5. C01–C14 Product Results <a class="header-anchor" href="#_5-c01–c14-product-results" aria-label="Permalink to &quot;5. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.6 criterion</th><th style="text-align:right;">Verdict</th><th>Executed observation</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td style="text-align:right;"><strong>PASS</strong></td><td>All four published S0.6 schemas compile; malformed structural and asserted <code>date-time</code> cases are rejected deterministically.</td></tr><tr><td>C02</td><td>Primary carrier and immutability</td><td style="text-align:right;"><strong>PASS</strong></td><td>Content-addressed revisions remain attributable, primary-carrier conflicts do not gain authority, and corrections remain separate evidence.</td></tr><tr><td>C03</td><td>Duplicate identity and provenance</td><td style="text-align:right;"><strong>PASS</strong></td><td>Different-content duplicates are quarantined; byte-identical observations project one node while retaining every deterministically ordered <code>source_id</code>.</td></tr><tr><td>C04</td><td>Serial continuity and asynchronous progress</td><td style="text-align:right;"><strong>PASS</strong></td><td>Stream gaps and duplicate sequences stay explicit, unrelated streams progress, and arrival order does not change output.</td></tr><tr><td>C05</td><td>Role authority</td><td style="text-align:right;"><strong>PASS</strong></td><td>Denied and undetermined authority branches remain distinct and cannot mutate reconstructed state.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td style="text-align:right;"><strong>PASS</strong></td><td>Illegal transitions are rejected; missing independent acceptance leaves completion undetermined and prevents advancement.</td></tr><tr><td>C07</td><td>Separation of duties and human approval</td><td style="text-align:right;"><strong>PASS</strong></td><td>Wrong approval type, missing assignment, disallowed role, missing approval decision, and self-approval remain <code>pending_human</code>; a valid assigned independent approval clears the gate.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td style="text-align:right;"><strong>PASS</strong></td><td>Covered-content tampering emits <code>INTEGRITY_MISMATCH</code>, excludes the object from authoritative nodes, and retains the failed source.</td></tr><tr><td>C09</td><td>Missing reference</td><td style="text-align:right;"><strong>PASS</strong></td><td>Missing dependencies and claim evidence remain visible and propagate an undetermined result without inventing facts.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only the affected prohibited-cycle subgraph is quarantined; unrelated valid nodes remain usable.</td></tr><tr><td>C11</td><td>Deterministic reconstruction</td><td style="text-align:right;"><strong>PASS</strong></td><td>Fixed-source permutations are byte-equivalent; canonical order is Unicode code-point order, including U+E000 before U+10000.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Contradictory reviews remain disputed until an authorized resolver acts; unauthorized decisions remain evidence but cannot clear the conflict.</td></tr><tr><td>C13</td><td>Recovery</td><td style="text-align:right;"><strong>PASS</strong></td><td>A fresh Reader reconstructs lifecycle, responsibility, dependencies, failures, recovery actions, and parent-child state consistently.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;"><strong>PASS</strong></td><td>Only the accepted authorized chain reaches archive, while the prior task/report/review/transition history remains reconstructable.</td></tr></tbody></table><h1 id="_6-s0-5-to-s0-6-product-delta" tabindex="-1">6. S0.5 to S0.6 Product Delta <a class="header-anchor" href="#_6-s0-5-to-s0-6-product-delta" aria-label="Permalink to &quot;6. S0.5 to S0.6 Product Delta&quot;">​</a></h1><h2 id="_6-1-c03-—-aggregation-without-provenance-loss" tabindex="-1">6.1 C03 — aggregation without provenance loss <a class="header-anchor" href="#_6-1-c03-—-aggregation-without-provenance-loss" aria-label="Permalink to &quot;6.1 C03 — aggregation without provenance loss&quot;">​</a></h2><p>I0.7 demonstrated conflict handling for same-ID, different-content candidates. S0.6 adds a second boundary: multiple byte-identical observations must not create duplicate nodes, but aggregation must not erase where those observations came from. V1.6.0 emits one canonical node with the complete, code-point-sorted <code>source_ids</code> list.</p><h2 id="_6-2-c07-—-approval-is-an-authorized-governance-object" tabindex="-1">6.2 C07 — approval is an authorized governance object <a class="header-anchor" href="#_6-2-c07-—-approval-is-an-authorized-governance-object" aria-label="Permalink to &quot;6.2 C07 — approval is an authorized governance object&quot;">​</a></h2><p>The S0.5 baseline demonstrated role separation and a high-risk human gate. S0.6 makes the authorization contract directly testable. An approval counts only when its object type is permitted, the actor has a matching Assignment, the role is allowed, the body carries an approval decision, and the actor is independent when the Profile requires it. Four negative branches remain pending rather than being treated as implicit approval.</p><h2 id="_6-3-c11-—-deterministic-means-locale-independent" tabindex="-1">6.3 C11 — deterministic means locale-independent <a class="header-anchor" href="#_6-3-c11-—-deterministic-means-locale-independent" aria-label="Permalink to &quot;6.3 C11 — deterministic means locale-independent&quot;">​</a></h2><p>S0.6 removes environmental ambiguity from canonical sorting. V1.6.0 replaces locale-dependent comparison with Unicode code-point ordering throughout object keys, sources, graph traversal, issues, and output collections. The U+E000/U+10000 fixture detects the UTF-16 code-unit ordering mistake that can otherwise pass ordinary ASCII tests.</p><h2 id="_6-4-compatibility-boundary" tabindex="-1">6.4 Compatibility boundary <a class="header-anchor" href="#_6-4-compatibility-boundary" aria-label="Permalink to &quot;6.4 Compatibility boundary&quot;">​</a></h2><p>CodeFlowMu&#39;s internal suite includes an explicit S0.5/I0.7 compatibility path. I0.7 remains the exact historical S0.5 product result; I0.8 does not rewrite its inputs, criteria, product version, or evidence package.</p><h1 id="_7-public-reproducer" tabindex="-1">7. Public Reproducer <a class="header-anchor" href="#_7-public-reproducer" aria-label="Permalink to &quot;7. Public Reproducer&quot;">​</a></h1><p>The formal archive contains a 29-file self-contained reproducer with a package lock, the product Reader, Protocol Validator, Profile, Fixtures, Runner, and exact official inputs. It requires Node.js 22 or newer and public npm registry access:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd public-reproducer</span></span>
<span class="line"><span>npm ci</span></span>
<span class="line"><span>npm test</span></span></code></pre></div><p>The test first verifies all seven upstream SHA-256 values, then calls the bundled CodeFlowMu <code>GovernanceReader</code>. The recorded clean-copy run and publication preflight both produce 14 PASS / 0 FAIL. The reproducer makes the conformance slice publicly inspectable without asserting that the private mother repository or full application is public.</p><h1 id="_8-retained-wp-13-evidence-gating-case" tabindex="-1">8. Retained WP-13 Evidence-Gating Case <a class="header-anchor" href="#_8-retained-wp-13-evidence-gating-case" aria-label="Permalink to &quot;8. Retained WP-13 Evidence-Gating Case&quot;">​</a></h1><p>WP-13 remains relevant to the engineering interpretation but is not rerun in I0.8. It records a role-separated workflow in which a completion-meaning claim was held until persistent evidence, a formal report, and QA verification existed. A later Gate C decision accepted delivery while activation, push/publication, and archive remained separate decisions.</p><p>This case supports evidence gating, staged authority, and same-task recovery. It does not prove hallucination elimination, universal false-claim detection, or S0.6 conformance. The C01–C14 result comes from the V1.6.0 product bundle, not from WP-13.</p><h1 id="_9-three-valued-governance-interpretation" tabindex="-1">9. Three-Valued Governance Interpretation <a class="header-anchor" href="#_9-three-valued-governance-interpretation" aria-label="Permalink to &quot;9. Three-Valued Governance Interpretation&quot;">​</a></h1><p>TMPA keeps semantic judgment separate from view classification:</p><table tabindex="0"><thead><tr><th>Judgment</th><th>Typical view</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>Required evidence and applicable rules establish the conclusion.</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>A deterministic violation excludes the affected evidence or action.</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>Evidence is missing or conflicting, or an authorized human decision is still required.</td></tr></tbody></table><p>I0.8 makes the separation observable. A wrong-type or self-issued approval is preserved but cannot satisfy C07. A missing reference in C09 leaves the dependent claim undetermined rather than false or complete. An unauthorized C12 resolution remains evidence but is invalid as a resolving act. Integrity failure in C08 quarantines covered content while preserving its source record.</p><h1 id="_10-evidence-integrity-and-publication-preflight" tabindex="-1">10. Evidence Integrity and Publication Preflight <a class="header-anchor" href="#_10-evidence-integrity-and-publication-preflight" aria-label="Permalink to &quot;10. Evidence Integrity and Publication Preflight&quot;">​</a></h1><p>The formal archive contains 195 files; 194 payload files are covered by its internal SHA-256 manifest. Its outer SHA-256 is <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code>. Independent publication preflight verified:</p><ul><li>ZIP structural integrity and ASCII-only entry names;</li><li>strict UTF-8 decoding for every file;</li><li>137 JSON files and 11 JSONL records;</li><li>194/194 internal SHA-256 entries;</li><li>byte identity for all seven official S0.6 inputs;</li><li>schema-valid C01–C14 result envelopes;</li><li>product Reader invocation without Reference Reader substitution;</li><li>a self-contained reproducer result of 14/14 PASS.</li></ul><p>The initial 2026-08-09 candidate archive is not published. It contained semantically identical but checkout-converted CRLF copies of the official inputs, an incorrect manifest-count statement, and no self-contained public rerun path. The corrected 2026-08-10 archive replaces it as the sole I0.8 formal package.</p><h1 id="_11-limitations" tabindex="-1">11. Limitations <a class="header-anchor" href="#_11-limitations" aria-label="Permalink to &quot;11. Limitations&quot;">​</a></h1><ol><li>The product and full-suite evidence is author-run; no independent organization has certified or adopted the implementation.</li><li>The CodeFlowMu implementation commit is local and is not represented as a public release, tag, or complete public source tree.</li><li>The public reproducer exposes the conformance slice, not the entire private CodeFlowMu application or its full Runtime/Shell environment.</li><li>Runtime retains one skipped test; the FCoP reference implementation retains two migrated-layout historical-example skips.</li><li>C11 evaluates a fixed fixture set and its declared permutations; it is not a formal proof over arbitrary graphs or hostile platforms.</li><li>C08 demonstrates governance-object integrity handling, not model truthfulness, identity authentication, installer protection, or Byzantine resilience.</li><li>Full-suite performance, representative SME burden, comparative baselines, and independent deployment remain open empirical questions.</li><li>WP-13 is a bounded governance case, not a hallucination-elimination benchmark.</li></ol><h1 id="_12-claim-ledger" tabindex="-1">12. Claim Ledger <a class="header-anchor" href="#_12-claim-ledger" aria-label="Permalink to &quot;12. Claim Ledger&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Claim</th><th>I0.8 disposition</th></tr></thead><tbody><tr><td>TMPA Core S0.6 defines C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.6.0 contains corresponding product mechanisms</td><td><strong>Implemented</strong></td></tr><tr><td>The fixed product bundle records 14/14 PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>The self-contained conformance slice can be publicly rerun</td><td><strong>Demonstrated</strong></td></tr><tr><td>The complete private CodeFlowMu application is publicly reproducible</td><td><strong>Not claimed</strong></td></tr><tr><td>The result has been independently certified or adopted</td><td><strong>Not demonstrated</strong></td></tr><tr><td>WP-13 proves hallucination elimination</td><td><strong>Prohibited conclusion</strong></td></tr></tbody></table><h1 id="_13-engineering-conclusion" tabindex="-1">13. Engineering Conclusion <a class="header-anchor" href="#_13-engineering-conclusion" aria-label="Permalink to &quot;13. Engineering Conclusion&quot;">​</a></h1><p>I0.8 advances the Implementation Case from an exact S0.5 product result to an exact-input S0.6 product result. CodeFlowMu V1.6.0 passes all fourteen mandatory criteria while directly exposing the S0.6 changes in provenance retention, approval authority, and locale-independent reconstruction. A self-contained reproducer narrows the gap between author-local product evidence and public inspection without misrepresenting the private full application as open or independently validated.</p><p>The result strengthens the engineering evidence for TMPA&#39;s implementability, not the logical truth of the theory. TMPA theory guides the system design, Core S0.6 fixes the evaluated requirements, FCoP supplies the collaboration and evidence protocol, CodeFlowMu is the application execution and consumption layer under test, and WP-13 is a bounded field case. Independent adoption and broader empirical evaluation remain future work.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The formal I0.8 archive is <a href="/joinwell52/evidence/tmpa/i0.8/tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip">tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip</a>. The adjacent file <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip.sha256</code> records <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code>.</p><p>I0.7 and its V1.4.1/S0.5 archive remain available at their versioned paths. The rejected I0.8 candidate is not part of the public publication set. Git history is the publication history; no parallel paper database has editorial authority.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.6,” commit <code>8989657e8fde6d2e55d7606ae0adacac14fec760</code>. GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.9.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” reference implementation commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.6.0 S0.6 Product Conformance,” implementation commit <code>62440a526a99d2fe55019d8bb95ad2425569fcb4</code>, 2026.</p><p>[5] TMPA Project. “I0.8 CodeFlowMu V1.6.0 S0.6 Evidence,” package <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810</code>, 2026.</p><p>[6] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” 2026.</p><p>[7] CodeFlowMu Project. “CodeFlowMu V1.4–V1.5 TMPA × FCoP × Application Unified Architecture,” <code>docs/TMPA-GOVERNANCE.md</code>. GitHub, 2026. <code>https://github.com/joinwell52-AI/codeflowmu/blob/main/docs/TMPA-GOVERNANCE.md</code>.</p>`,70))])}const f=a(s,[["render",c]]);export{b as __pageData,f as default};
